styles:
.reset-box-sizing,
.reset-box-sizing *,
.reset-box-sizing *:before,
.reset-box-sizing *:after {
  -webkit-box-sizing: content-box;
     -moz-box-sizing: content-box;
          box-sizing: content-box;
}
.reset-element,
.reset-element a, 
.reset-element input {
  font-family: "Segoe UI", "微軟正黑體", "Microsoft JhengHei", Arial, "新細明體";
}
